import{_ as o}from"./chunks/console-approval-workflows.B1vbzRIQ.js";import{_ as a,o as r,c as t,a3 as s}from"./chunks/framework.DhF4LrUq.js";const u=JSON.parse('{"title":"Work with approvals","description":"Work with approvals - compose approval workflows in the Console, sign your step, reject with a reason, and restart a rejected round.","frontmatter":{"description":"Work with approvals - compose approval workflows in the Console, sign your step, reject with a reason, and restart a rejected round."},"headers":[],"relativePath":"how-to/console/approvals.md","filePath":"how-to/console/approvals.md"}'),n={name:"how-to/console/approvals.md"};function i(p,e,l,h,d,c){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="work-with-approvals" tabindex="-1">Work with approvals <a class="header-anchor" href="#work-with-approvals" aria-label="Permalink to &quot;Work with approvals&quot;">​</a></h1><p>Approvals are the human gate on the release path: a workflow binds sign-off steps to a release, and the release cannot cross to APPROVED until the chain is satisfied. You compose workflows on the <strong>Approval workflows</strong> screen and sign them on the <a href="/shipperdog/snapshot/how-to/console/releases">release dashboard</a>.</p><p><img src="'+o+'" alt="The Approval workflows screen"></p><p>How the engine evaluates groups and conditions is covered in <a href="/shipperdog/snapshot/concepts/approvals-gates">approvals and gates</a>.</p><h2 id="compose-an-approval-workflow" tabindex="-1">Compose an approval workflow <a class="header-anchor" href="#compose-an-approval-workflow" aria-label="Permalink to &quot;Compose an approval workflow&quot;">​</a></h2><ol><li><p>Open <strong>Approval workflows</strong> and click <strong>New definition</strong>.</p></li><li><p>Give it a <strong>Binding name</strong> (kebab-case, for example <code>two-person</code>) and optionally a <strong>Starting ring</strong> — the workflow binds to releases beginning on that ring.</p></li><li><p>Build the chain as ordered <strong>groups</strong>:</p><ul><li>Each group carries a <strong>Mode</strong>: <strong>ALL</strong> — every step must approve — or <strong>ANY</strong> — first approval satisfies.</li><li>Each <strong>step</strong> names a <strong>Required role</strong> from the five-role vocabulary: QA, Security, Compliance, Product (App Owner), or Release Manager.</li><li>A step may narrow to a <strong>Tenant scope</strong> (only releases targeting that tenant) and carry a <strong>Condition</strong> — <em>environment equals</em> a code, or <em>feature-flag contains</em> a key.</li></ul></li><li><p>Save. The list shows each definition with its chain summary.</p></li></ol><p>Editing an existing workflow reopens the same dialog. Changes affect the rounds a release opens from that point on — a running round keeps the shape it was opened with.</p><h2 id="sign-your-step" tabindex="-1">Sign your step <a class="header-anchor" href="#sign-your-step" aria-label="Permalink to &quot;Sign your step&quot;">​</a></h2><ol><li><p>Open the release (Releases — View). The <strong>Approvals</strong> block shows the live round: its number, status, and the workflow name, with the <strong>Waiting on</strong> list naming the roles that can act.</p></li><li><p>On a step waiting on you, click <strong>Approve</strong>. Your signature — name and moment — records on the step.</p></li><li><p><strong>Reject</strong> opens a dialog: the <strong>reason is required</strong> and is recorded permanently. A rejection terminates the round and blocks the release&#39;s progression until rework.</p></li></ol><h2 id="restart-a-rejected-round" tabindex="-1">Restart a rejected round <a class="header-anchor" href="#restart-a-rejected-round" aria-label="Permalink to &quot;Restart a rejected round&quot;">​</a></h2><p>While the release sits in approval pending with a rejected round, <strong>Restart approval round (rework)</strong> opens a fresh round of the same workflow. The earlier rounds stay visible beneath the current one with their rejection reasons — nothing is erased.</p><h2 id="read-the-record" tabindex="-1">Read the record <a class="header-anchor" href="#read-the-record" aria-label="Permalink to &quot;Read the record&quot;">​</a></h2><ul><li>Steps that approved show who signed and when.</li><li>Skipped steps (an ANY sibling approved first) carry the skip rationale.</li><li>A release with no bound policy states that plainly: it crossed without sign-offs, and its frozen manifest records the required-approver set.</li></ul><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/releases">work with releases</a> · <a href="/shipperdog/snapshot/how-to/console/quality-gates">quality gates</a> · <a href="/shipperdog/snapshot/concepts/approvals-gates">approvals and gates concepts</a></p>',14)])])}const f=a(n,[["render",i]]);export{u as __pageData,f as default};
